INSERT INTO public.campaigns (id, title, description, short_description, category, target_amount, current_amount, status, deadline, images, documents, created_by, created_at, updated_at, videos, is_recommended, main_image_index, campaign_type, title_en, short_description_en, description_en) VALUES ('8aaa5d8f-67a5-4325-b67d-05bcc4ab0899', 'Ремонт на детско отделение в Ботевград', 'Детското отделение в Ботевград се нуждае от спешен ремонт – остаряла база, липса на модерно оборудване и неподходящи условия за малките пациенти. Целта на кампанията е да се съберат средства за ремонт на стаите, закупуване на нови легла и подобряване на условията за лечение.', 'Събиране на средства за обновяване на детското отделение.', 'healthcare', 15000.00, 0.00, 'active', '2026-12-30 00:00:00+00', '{https://zjzyybdvbgovnvftnfod.supabase.co/storage/v1/object/public/campaign-images/f98ae767-6dbe-44ba-bab8-c7fbd680354e/1775552313235-bdo4hgeey4.jpeg,https://zjzyybdvbgovnvftnfod.supabase.co/storage/v1/object/public/campaign-images/f98ae767-6dbe-44ba-bab8-c7fbd680354e/1775552313751-60jdzydqm8s.jpg,https://zjzyybdvbgovnvftnfod.supabase.co/storage/v1/object/public/campaign-images/f98ae767-6dbe-44ba-bab8-c7fbd680354e/1775552313984-3z47qpkqbhm.jpg,https://zjzyybdvbgovnvftnfod.supabase.co/storage/v1/object/public/campaign-images/f98ae767-6dbe-44ba-bab8-c7fbd680354e/1775552314343-c8fl3y18asd.jpg,https://zjzyybdvbgovnvftnfod.supabase.co/storage/v1/object/public/campaign-images/f98ae767-6dbe-44ba-bab8-c7fbd680354e/1775552314858-y6uy0f5gv3.jpg}', '{}', 'f98ae767-6dbe-44ba-bab8-c7fbd680354e', '2026-04-07 08:58:37.185107+00', '2026-04-24 07:58:36.129098+00', '{}', false, 1, 'one_time', NULL, NULL, NULL);
